  ('lord_01', 'キンランキリュウ', 10, '魚', 'fish', '##d8a93c', '##ffd76a', 'swim', null, null, false, '01', '日本一高い水面から天へ昇る、桐生織の金糸をまとった龍。', 901),
  ('lord_02', 'トダイオウイカ', 10, '頭足', 'squid', '##19384f', '##7594ab', 'swim', null, null, false, '02', '海にいるはずのものが、なぜか人工池の底にいる。', 902),
  ('lord_03', 'オオエドナマズ', 10, '魚', 'fish', '##2d4c63', '##7594ab', 'swim', null, null, false, '03', 'この鯰が寝返りを打つと、日本一荒れる水面になる。', 903),
  ('lord_04', 'オオモリノリクジラ', 10, '海獣', 'whale', '##325168', '##708fa6', 'swim', null, null, false, '04', '埋め立てで消えた大森の海苔ひびを、全身にまとっている。', 904),
  ('lord_05', 'カガミアユ', 10, '魚', 'fish', '##1b3a51', '##7796ad', 'swim', null, null, false, '05', '日本一静かな水面を鏡と見立て、その裏側を泳ぐ銀の鮎。', 905),
  ('lord_06', 'コガネオオウナギ', 10, '魚', 'eel', '##d8a93c', '##ffd76a', 'swim', null, null, false, '06', '今切口が開いた日から湖にいる、全長5mの金の鰻。', 906),
  ('lord_07', 'オオウミガマ', 10, '魚', 'fish', '##3c5b72', '##7a99b0', 'swim', null, null, false, '07', '蒲郡の名に潜んでいた蝦蟇。ナイターの照明で緑に光る。', 907),
  ('lord_08', 'マネキウミウシ', 10, '貝', 'spiral', '##9f895f', '##ddc79d', 'crawl', null, null, false, '08', '常滑焼の招き猫が海に沈み、片手を上げたまま生き物になった。', 908),
  ('lord_09', 'ツ', 10, '魚', 'fish', '##1b3a51', '##638299', 'swim', null, null, false, '09', '日本一短い市名にちなむ、日本一短い名前の生き物。本名は誰も知らない。', 909),
  ('lord_10', 'サンゴクオオガニ', 10, '甲殻', 'crab', '##ad5b41', '##f5a389', 'crawl', null, null, false, '10', '甲羅に三つの国の紋が浮かぶ、越前ガニの主。', 910),
  ('lord_11', 'ビワヒキマス', 10, '魚', 'fish', '##335269', '##7b9ab1', 'swim', null, null, false, '11', '鰭が琵琶の弦になっていて、泳ぐと湖の底から音がする。', 911),
  ('lord_12', 'スミハキオオダコ', 10, '頭足', 'octopus', '##3a5970', '##6e8da4', 'swim', null, null, false, '12', '売上日本一の水面を、一夜で墨に沈める。', 912),
  ('lord_13', 'アマゴロモクラゲ', 10, 'クラゲ', 'jelly', '##b0bfcf', '##ffffff', 'float', null, null, false, '13', '白い衣をまとった尼のようなクラゲ。人工池にだけ湧く。', 913),
  ('lord_14', 'ウズシオダイ', 10, '魚', 'fish', '##2e4d64', '##628198', 'swim', null, null, false, '14', '渦の中心にしかいない。渦が消えると一緒に消える。', 914),
  ('lord_15', 'マンマルガメ', 10, 'その他', 'turtle', '##908068', '##d8c8b0', 'swim', null, null, false, '15', '甲羅が完全な円。うちわのように水を煽いで進む。', 915),
  ('lord_16', 'アイゾメオオエイ', 10, '魚', 'ray', '##2f4f80', '##5d7dae', 'swim', null, null, false, '16', '通ったあとの海が藍色に染まる。児島のデニムはここから始まった。', 916),
  ('lord_17', 'オオトリイガキ', 10, '貝', 'shell', '##ad976d', '##ebd5ab', 'crawl', null, null, false, '17', '大鳥居の柱に張り付いて、鳥居の形に育ってしまった牡蠣。', 917),
  ('lord_18', 'ヤコウオオイカ', 10, '頭足', 'squid', '##1d3c53', '##7998af', 'swim', null, null, false, '18', '周南の工場の光を体に映して泳ぐ。', 918),
  ('lord_19', 'ガンリュウフグ', 10, '魚', 'puffer', '##17364d', '##69889f', 'swim', null, null, false, '19', '二本の棘を刀のように構える。巌流島の沖にいる。', 919),
  ('lord_20', 'ワカマツモ', 10, '海藻', 'weed', '##658c49', '##9bc27f', 'fix', null, null, false, '20', '松の形をした赤い海藻。死の海と呼ばれた洞海湾が甦った証。', 920),
  ('lord_21', 'アシワケアコウ', 10, '魚', 'fish', '##1c3b52', '##64839a', 'swim', null, null, false, '21', '遠賀川の葦をかき分けて現れる、真っ赤なアコウ。', 921),
  ('lord_22', 'ハカタオリサバ', 10, '魚', 'fish', '##38576e', '##628198', 'swim', null, null, false, '22', '体に博多織の献上柄が浮かぶ。街の真ん中の水面に出る。', 922),
  ('lord_23', 'ヒキヤマイカ', 10, '頭足', 'squid', '##37566d', '##7594ab', 'swim', null, null, false, '23', '唐津くんちの曳山そのものの姿をした、呼子の巨大烏賊。', 923),
  ('lord_24', 'コトノウミリュウ', 10, '魚', 'fish', '##39586f', '##6d8ca3', 'swim', null, null, false, '24', '大村湾の古名は「琴の海」。日本で最初の水面の主。', 924)
